<?php
namespace App\Controllers;
use App\Helpers\{View,Csrf,Flash,OrderWorkflow}; use App\Middlewares\AdminMiddleware; use App\Config\Database;
final class AdminOrderController {
    public function index():void { AdminMiddleware::handle(); $pdo=Database::connection();OrderWorkflow::ensureSchema($pdo);$orders=$pdo->query('SELECT o.*,os.name status_name,u.username,u.first_name,u.last_name FROM orders o JOIN order_statuses os ON os.id=o.status_id JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll();$statusRows=$pdo->query('SELECT * FROM order_statuses ORDER BY id')->fetchAll();$byName=[];foreach($statusRows as $status)$byName[$status['name']]=$status;foreach($orders as &$order){$names=OrderWorkflow::allowedStatusNames($order);$order['available_statuses']=array_values(array_intersect_key($byName,array_flip($names)));}unset($order);View::render('admin/orders',['title'=>'Pedidos','orders'=>$orders]); }
    public function status(string $id):void { AdminMiddleware::handle();Csrf::validate();$pdo=Database::connection();OrderWorkflow::ensureSchema($pdo);$orderQuery=$pdo->prepare('SELECT o.delivery_method,os.name status_name FROM orders o JOIN order_statuses os ON os.id=o.status_id WHERE o.id=?');$orderQuery->execute([(int)$id]);$order=$orderQuery->fetch();$status=(int)($_POST['status_id']??0);$names=$order?OrderWorkflow::allowedStatusNames($order):[];$marks=$names?implode(',',array_fill(0,count($names),'?')):'NULL';$valid=$pdo->prepare("SELECT id FROM order_statuses WHERE id=? AND name IN ($marks)");$valid->execute(array_merge([$status],$names));if(!$order||$valid->fetchColumn()===false){Flash::set('error','Ese estado no corresponde al siguiente paso del pedido.');header('Location: /admin/orders');exit;}$s=$pdo->prepare('UPDATE orders SET status_id=?,updated_at=NOW() WHERE id=?');$s->execute([$status,(int)$id]);Flash::set('success','Estado del pedido actualizado.');header('Location: /admin/orders'); }
}
